import type { NextRequest } from "next/server";

export function middleware(request: NextRequest) {
  // Check for auth token in cookies
  const authToken = request.cookies.get("auth_token")?.value;

  // For /app/* routes, check authentication
  if (request.nextUrl.pathname.startsWith("/app")) {
    // If no auth token, allow the request but the page will handle showing auth modal
    // We're not redirecting, just letting the page know the auth status
    const response = NextResponse.next();

    // Add a header to indicate auth status (optional, for debugging)
    response.headers.set("x-auth-status", authToken ? "authenticated" : "unauthenticated");

    return response;
  }

  return NextResponse.next();
}

export const config = {
  matcher: ["/app/:path*"],
};

